// Package versions is the debugger's support table: the
// Collector releases it verified, each with its dependency set and
// component catalog, generated by scripts/dependency-set.ps1 into
// build/versions/<version>/ and embedded here. It holds data and lookups
// only and imports nothing from this repository.
package versions

import (
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"slices"
	"strings"
	"sync"

	"golang.org/x/mod/semver"
)

// Oldest is the oldest Collector release a runtime can be built for;
// older manifests are refused before building.
const Oldest = "0.160.0"

// files are the release directories (every release is 0.x so far). The
// generator imports this package before a new release has its files.
//
//go:embed 0.*
var files embed.FS

// Release is a verified Collector release.
type Release struct {
	// Version is the release, such as "0.162.0".
	Version string
	// GoMod and GoSum are the dependency set: the go.mod and go.sum of
	// building every core and contrib component with the debugger at this
	// release. Every build for the release uses the whole set.
	GoMod, GoSum []byte
	// Catalog lists the release's core and contrib components.
	Catalog *Catalog
}

// Catalog is a release's components, read from their metadata at that
// release.
type Catalog struct {
	CollectorVersion string `json:"collector_version"`
	// Source names the release manifest the catalog was generated from.
	Source     string      `json:"source"`
	Components []Component `json:"components"`
	// Providers and Converters are the release manifest's gomod entries.
	Providers  []string `json:"providers"`
	Converters []string `json:"converters"`
	// Replaces are the release manifest's replaces the dependency set was
	// resolved with.
	Replaces []string `json:"replaces"`
}

// Component is one catalog entry.
type Component struct {
	// Kind is the manifest list: receivers, processors, exporters,
	// connectors or extensions.
	Kind string `json:"kind"`
	// Type is the component type configurations name.
	Type string `json:"type"`
	// DeprecatedType is the old type a component still accepts under its
	// metadata's deprecated_type, such as the otlp exporter's "otlp" for
	// "otlp_grpc"; configurations may name either.
	DeprecatedType string `json:"deprecated_type,omitempty"`
	// GoMod is the manifest entry, "<module> <version>".
	GoMod string `json:"gomod"`
	// Import is the package when it is not the module's root.
	Import string `json:"import,omitempty"`
	// Class is "core" or "contrib".
	Class string `json:"class"`
	// Stability maps a stability level to the signals at that level, as
	// the component's metadata states them.
	Stability map[string][]string `json:"stability"`
	// Unsupported says why the debugger leaves the component out of the
	// "all core and contrib" preset; empty when it is included.
	Unsupported string `json:"unsupported,omitempty"`
}

// Module is the component's module path.
func (c Component) Module() string {
	mod, _, _ := strings.Cut(c.GoMod, " ")
	return mod
}

// Table is a support table: the verified releases.
type Table struct {
	releases []*Release
}

// NewTable makes a table of releases, as tests do to treat a release as
// unverified.
func NewTable(releases ...*Release) *Table {
	t := &Table{releases: slices.Clone(releases)}
	slices.SortFunc(t.releases, func(a, b *Release) int { return Compare(a.Version, b.Version) })
	return t
}

var embedded = sync.OnceValues(func() (*Table, error) {
	dirs, err := fs.ReadDir(files, ".")
	if err != nil {
		return nil, err
	}
	var releases []*Release
	for _, d := range dirs {
		if !d.IsDir() {
			continue
		}
		r := &Release{Version: d.Name()}
		if r.GoMod, err = fs.ReadFile(files, d.Name()+"/dependencies.mod"); err != nil {
			return nil, err
		}
		if r.GoSum, err = fs.ReadFile(files, d.Name()+"/dependencies.sum"); err != nil {
			return nil, err
		}
		raw, err := fs.ReadFile(files, d.Name()+"/catalog.json")
		if err != nil {
			return nil, err
		}
		if err := json.Unmarshal(raw, &r.Catalog); err != nil {
			return nil, fmt.Errorf("versions: %s/catalog.json: %w", d.Name(), err)
		}
		releases = append(releases, r)
	}
	return NewTable(releases...), nil
})

// Embedded is this debugger's support table.
func Embedded() *Table {
	t, err := embedded()
	if err != nil {
		panic(err) // The embedded files are generated and tested.
	}
	return t
}

// Versions lists the verified releases, oldest first.
func (t *Table) Versions() []string {
	out := make([]string, 0, len(t.releases))
	for _, r := range t.releases {
		out = append(out, r.Version)
	}
	return out
}

// Release returns a verified release, or nil.
func (t *Table) Release(version string) *Release {
	for _, r := range t.releases {
		if r.Version == strings.TrimPrefix(version, "v") {
			return r
		}
	}
	return nil
}

// Newest is the newest verified release, or "" for an empty table.
func (t *Table) Newest() string {
	if len(t.releases) == 0 {
		return ""
	}
	return t.releases[len(t.releases)-1].Version
}

// Support is how the table treats a Collector release.
type Support string

const (
	// Verified releases have a dependency set, a catalog and conformance
	// evidence.
	Verified Support = "verified"
	// Unverified releases are not in the table, from Oldest on: they build
	// through the user's module source without a pinned set.
	Unverified Support = "unverified"
)

// Check says how a release builds; a release before Oldest, or one that is
// not a version, is an error naming the oldest supported release.
func (t *Table) Check(version string) (Support, error) {
	v := strings.TrimPrefix(version, "v")
	if !semver.IsValid("v" + v) {
		return "", fmt.Errorf("version %q is not a Collector release version", version)
	}
	if Compare(v, Oldest) < 0 {
		return "", fmt.Errorf("the Collector release %s is older than %s, the oldest release the debugger builds", v, Oldest)
	}
	if t.Release(v) != nil {
		return Verified, nil
	}
	return Unverified, nil
}

// Compare compares two releases written with or without a "v".
func Compare(a, b string) int {
	return semver.Compare("v"+strings.TrimPrefix(a, "v"), "v"+strings.TrimPrefix(b, "v"))
}
